import time
from functools import wraps

def onbellekle(ttl=None, saat=time.monotonic):
    def dekorator(f):
        cache = {}
        isabet = [0]
        iska = [0]

        @wraps(f)
        def sarmal(*args, **kwargs):
            # İsimli argümanların sırasından bağımsız bir anahtar oluştur
            # Dict'leri hashleyemediği için tuple'a çeviriyoruz (sadece hashlenebilenler için)
            try:
                # Kwargs'ı sıralı bir tuple'a dönüştürerek isimli argüman sırasını eşitle
                kwarg_items = tuple(sorted(kwargs.items()))
                anahtar = (args, kwarg_items)
            except TypeError:
                # Hashlenemeyen bir argüman varsa direkt çalıştır
                iska[0] += 1
                return f(*args, **kwargs)

            now = saat()
            if anahtar in cache:
                deger, zaman = cache[anahtar]
                # ttl geçtikten SONRA geçersiz olur (tam ttl anında hala geçerlidir)
                if ttl is None or now - zaman < ttl:
                    isabet[0] += 1
                    return deger

            iska[0] += 1
            deger = f(*args, **kwargs)
            cache[anahtar] = (deger, now)
            return deger

        def temizle():
            cache.clear()

        def bilgi():
            return {"isabet": isabet[0], "iska": iska[0]}

        sarmal.temizle = temizle
        sarmal.bilgi = bilgi
        return sarmal
    return dekorator

# Test ortamını simüle etmek için hızlıca kontrol edelim
def test_logic():
    @onbellekle()
    def test_func(x, y=2):
        return x + y

    assert test_func(2, y=3) == 5
    assert test_func(2, y=3) == 5 # isabet
    assert test_func(2, n=3) # iska (farklı argüman adı veya değer)
    assert test_func(2, y=3) == 5 # isabet
    print("Mantık testleri başarılı")

test_logic()

import time
