def onbellekle(ttl=None, saat=time.monotonic):
    """
    Fonksiyon sonuçlarını argümanlarına göre önbelleğe alan dekoratör.
    """
    def dekorator(f):
        # Her dekore edilen fonksiyonun önbelleği ayrıdır.
        cache = {}
        # isabet ve iska değişkenlerini nonlocal kullanmak için mutable nesneye sarıyoruz
        # veya doğrudan nonlocal ile tanımlıyoruz.
        stats = {'isabet': 0, 'iska': 0}

        @wraps(f)
        def sarmal(*args, **kwargs):
            # 1. Argümanları handle etme (Hashlenemeyen argümanlar için)
            # 2. İsimli argümanların yazılış sırası önemsiz (sorted)
            # 3. Argümanların birleşimi (args ve kwargs)

            try:
                # Kwargları sıralı tuple yapıyoruz ki {a:1, b:2} ile {b:2, a:1} aynı olsun
                kwarg_tuple = tuple(sorted(kwargs.items()))
                anahtar = (args, kwarg_tuple)

                # Hashlenemeyen bir şey varsa KeyError veya TypeError fırlatır
                # hash(anahtar) denemesi yaparak bunu hızlıca yakalayabiliriz
                hash(anahtar)
            except TypeError:
                # Hashlenemeyen bir argüman var: doğrudan çalıştır
                stats['iska'] += 1
                return f(*args, **kwargs)

            now = saat()

            if anahtar in cache:
                deger, zaman = cache[anahtar]
                # ttl (saniye) verilirse kayıt eklendiği andan ttl saniye geçtikten SONRA geçersiz olur
                # Yani now - zaman < ttl ise hala geçerlidir.
                if ttl is None or (now - zaman) < ttl:
                    stats['isabet'] += 1
                    return deger

            # Geçersiz veya yok: yeniden çalıştır
            stats['iska'] += 1
            deger = f(*args, **kwargs)
            cache[anahtar] = (deger, now)
            return deger

        def temizle():
            cache.clear()

        def bilgi():
            return {"isabet": stats['isabet'], "iska": stats['iska']}

        sarmal.temizle = temizle
        sarmal.bilgi = bilgi
        return sarmal
    return dekorator

# Test 1: Temel fonksiyonlar
def test_suite():
    import time

    # Test: İsimli argüman sırası ve değerleri
    call_count = []
    @onbellekle()
    def us(x, n=2):
        call_count.append(x)
        return x ** n

    assert us(2, n=3) == 8
    assert us(2, n=3) == 8 # isabet
    assert us(2, n=4) == 16 # iska
    assert len(call_count) == 2

    # Test: TTL kontrolü
    @onbellekle(ttl=1)
    def gecikmeli(x):
        return x

    gecikmeli(1) # iska=1, isabet=0
    assert gecikmeli.bilgi() == {"isabet": 0, "iska": 1}
    gecikmeli(1) # isabet=1
    assert gecikmeli.bilgi() == {"isabet": 1, "iska": 1}

    time.sleep(1.1)

    gecikmeli(1) # iska=2 (ttl doldu)
    assert gecikmeli.bilgi() == {"isabet": 1, "iska": 2}

    # Test: Hashlenemeyen argüman (liste)
    @onbellekle()
    def liste_test(l):
        return sum(l)

    assert liste_test([1, 2]) == 3 # iska=1
    assert liste_test([1, 2]) == 3 # iska=2 (hashlenemez çünkü liste)

    # Test: Docstring ve Name koruma
    def merhaba():
        """Merhaba Dünya"""
        pass

    @onbellekle()
    def merhaba_dekore():
        """Merhaba Dünya"""
        pass

    assert merhaba_dekore.__name__ == "merhaba_dekore"
    assert merhaba_dekore.__doc__ == "Merhaba Dünya"

    print("Tüm mantık testleri geçti.")

test_suite()

